---
import Button from '@/components/global/button';
import FormSubmission from '@/components/global/newsletter/form-submission';
import { HeadingType, TextAlignment } from '@/utils/formattingEnums';
import SectionHeading from '@/components/global/section-heading.astro';
import Picture from 'astro/components/Picture.astro';
import {
  CTA_DEFAULTS,
  CTA_PRIMARY,
  CTA_VARIANT,
  CTA_VARIANT_IDS,
  MODAL_IMAGES,
  MODAL_CONFIG,
  type Attribution,
} from '@/constants/cta';
import { addUTMParams } from '@/utils/tracking';
import { SignupType, SignupSource } from '@/constants/signup';
import type { ImageMetadata } from 'astro';

interface Props {
  attribution: Attribution;
  source: SignupSource;
  image?: ImageMetadata;
  imageAlt?: string;
}

const {
  attribution,
  source,
  image = MODAL_IMAGES.image,
  imageAlt = MODAL_CONFIG.imageAlt,
} = Astro.props;

const primaryHref = addUTMParams(CTA_PRIMARY.buttonLink, attribution, 'popup');
const variantHref = CTA_VARIANT ? addUTMParams(CTA_VARIANT.buttonLink, attribution, 'popup') : '';
---

<div
  id="modal-popup"
  class="modal-popup"
  role="dialog"
  aria-modal="true"
  aria-labelledby="modal-title"
  data-attribution={attribution}
>
  <div class="modal-backdrop" data-modal-close></div>
  <div class="modal-content" role="document">
    <button class="modal-close" data-modal-close aria-label="Close modal">
      <span aria-hidden="true">&times;</span>
    </button>

    <!-- Primary variant -->
    <div data-variant="primary" class="hidden">
      {CTA_PRIMARY.showForm ? (
        <FormSubmission
          client:only="react"
          heading={CTA_PRIMARY.modalHeading}
          body={CTA_PRIMARY.bodyText}
          layout="compact"
          signupType={SignupType.Popup}
          source={source}
        />
      ) : (
        <>
          <SectionHeading
            headingType={HeadingType.h2}
            heading={CTA_PRIMARY.modalHeading}
            textAlignment={TextAlignment.center}
          />
          <div class="mt-6">
            <Picture src={image} alt={imageAlt} />
            <div class="modal-body mt-6 mb-6 items-center text-center">
              <p>{CTA_PRIMARY.bodyText}</p>
            </div>
          </div>
          <div class="modal-buttons">
            <Button
              href={primaryHref}
              label={CTA_PRIMARY.modalButtonText}
              variant="default"
              data-ph-capture-attribute-button-click={CTA_DEFAULTS.postHogButtonID}
              data-ph-capture-attribute-test-variant={CTA_VARIANT_IDS.primary}
              className="modal-button-primary"
              client:load
            />
            <Button
              href="#"
              label={MODAL_CONFIG.closeButtonText}
              variant="secondary"
              size="sm"
              className="modal-button-secondary"
              data-modal-close
              client:load
            />
          </div>
        </>
      )}
    </div>

    {/* Test variant: rendered only when CTA_VARIANT is populated in cta.ts */}
    {CTA_VARIANT && (
      <div data-variant="variant" class="hidden">
        {CTA_VARIANT.showForm ? (
          <FormSubmission
            client:only="react"
            heading={CTA_VARIANT.modalHeading}
            body={CTA_VARIANT.bodyText}
            layout="compact"
            signupType={SignupType.Popup}
            source={source}
          />
        ) : (
          <>
            <SectionHeading
              headingType={HeadingType.h2}
              heading={CTA_VARIANT.modalHeading}
              textAlignment={TextAlignment.center}
            />
            <div class="mt-6">
              <Picture src={image} alt={imageAlt} />
              <div class="modal-body mt-6 mb-6 items-center text-center">
                <p>{CTA_VARIANT.bodyText}</p>
              </div>
            </div>
            <div class="modal-buttons">
              <Button
                href={variantHref}
                label={CTA_VARIANT.modalButtonText}
                variant="default"
                data-ph-capture-attribute-button-click={CTA_DEFAULTS.postHogButtonID}
                data-ph-capture-attribute-test-variant={CTA_VARIANT_IDS.variant}
                className="modal-button-primary"
                client:load
              />
              <Button
                href="#"
                label={MODAL_CONFIG.closeButtonText}
                variant="secondary"
                size="sm"
                className="modal-button-secondary"
                data-modal-close
                client:load
              />
            </div>
          </>
        )}
      </div>
    )}
  </div>

  <script>
    import { AB_TEST_ENABLED, MODAL_CONFIG } from '@/constants/cta';
    import { shouldShowModal, recordModalShown } from '@/utils/storage';

    document.addEventListener('DOMContentLoaded', () => {
      const modal = document.getElementById('modal-popup') as HTMLElement;

      if (!modal) return;

      // Pick random variant (or always primary if A/B testing disabled)
      const variantId =
        AB_TEST_ENABLED && Math.random() >= 0.5 ? 'variant' : 'primary';

      // Show chosen variant content
      const variantEl = modal.querySelector(`[data-variant="${variantId}"]`);
      if (variantEl) {
        variantEl.classList.remove('hidden');
      }

      // Check if we should show the modal based on frequency control
      if (!shouldShowModal(MODAL_CONFIG.displayIntervalDays)) {
        return;
      }

      // Show modal after configured delay
      setTimeout(() => {
        modal.classList.add('modal-show');
        document.body.style.overflow = 'hidden';

        // Record that we showed the modal
        recordModalShown();

        // Focus trap: Get all focusable elements
        const focusableElements = modal.querySelectorAll(
          'button, [href], input, select, textarea, [tabindex]:not([tabindex="-1"])'
        );
        const firstFocusable = focusableElements[0] as HTMLElement;
        const lastFocusable = focusableElements[
          focusableElements.length - 1
        ] as HTMLElement;

        // Set initial focus
        firstFocusable?.focus();

        // Trap focus within modal
        const handleTabKey = (e: KeyboardEvent) => {
          if (e.key !== 'Tab') return;

          if (e.shiftKey) {
            if (document.activeElement === firstFocusable) {
              lastFocusable?.focus();
              e.preventDefault();
            }
          } else {
            if (document.activeElement === lastFocusable) {
              firstFocusable?.focus();
              e.preventDefault();
            }
          }
        };

        modal.addEventListener('keydown', handleTabKey);
      }, MODAL_CONFIG.delayMilliSeconds);

      // Close modal function
      const closeModal = () => {
        modal.classList.remove('modal-show');
        document.body.style.overflow = '';
      };

      // ESC key closes modal
      document.addEventListener('keydown', (e) => {
        if (e.key === 'Escape' && modal.classList.contains('modal-show')) {
          closeModal();
        }
      });

      // Click on backdrop or close button closes modal
      const closeElements = modal.querySelectorAll('[data-modal-close]');
      closeElements.forEach((element) => {
        element.addEventListener('click', (e) => {
          e.preventDefault();
          closeModal();
        });
      });
    });
  </script>
</div>

