---
import { HeadingType, TextAlignment } from '@/utils/formattingEnums';
import Button from '@/components/global/button';
import FormSubmission from '@/components/global/newsletter/form-submission';
import { getImage } from 'astro:assets';
import SectionHeading from '@/components/global/section-heading.astro';
import {
  CTA_DEFAULTS,
  CTA_PRIMARY,
  CTA_VARIANT,
  CTA_VARIANT_IDS,
  BANNER_IMAGES,
  type Attribution,
} from '@/constants/cta';
import { addUTMParams } from '@/utils/tracking';
import { SignupType, SignupSource } from '@/constants/signup';

interface Props {
  attribution: Attribution;
  source: SignupSource;
}

const { attribution, source } = Astro.props;

const optimizedBackground = await getImage({
  src: BANNER_IMAGES.image,
  format: 'avif',
});

const primaryHref = addUTMParams(CTA_PRIMARY.buttonLink, attribution, 'inline');
const variantHref = CTA_VARIANT ? addUTMParams(CTA_VARIANT.buttonLink, attribution, 'inline') : '';
---

<section
  class="container mx-auto max-w-6xl"
  data-cta-banner
  data-attribution={attribution}
>
  <div
    class="relative overflow-hidden rounded-4xl border-2 border-blue-300 bg-cover bg-center bg-no-repeat px-5 py-10 lg:p-10"
    style={`background-image: url(${optimizedBackground.src});`}
  >
    <!-- Primary variant -->
    <div
      class="relative z-10 hidden flex-col items-center text-center"
      data-variant="primary"
    >
      {CTA_PRIMARY.showForm ? (
        <FormSubmission
          client:only="react"
          heading={CTA_PRIMARY.heading}
          body={CTA_PRIMARY.bodyText}
          layout="card"
          signupType={SignupType.Banner}
          source={source}
        />
      ) : (
        <>
          <SectionHeading
            headingType={HeadingType.h2}
            heading={CTA_PRIMARY.heading}
            textAlignment={TextAlignment.center}
          />
          <div class="mt-4 flex flex-wrap justify-center gap-4 md:mt-12">
            <Button
              size="lg"
              href={primaryHref}
              data-ph-capture-attribute-button-click={CTA_DEFAULTS.postHogButtonID}
              data-ph-capture-attribute-test-variant={CTA_VARIANT_IDS.primary}
            >
              {CTA_PRIMARY.buttonText}
            </Button>
            <SectionHeading
              headingType={HeadingType.h3}
              heading={CTA_PRIMARY.subHeading}
              textAlignment={TextAlignment.center}
            />
            <p>{CTA_PRIMARY.bodyText}</p>
          </div>
        </>
      )}
    </div>

    {/* Test variant: rendered only when CTA_VARIANT is populated in cta.ts */}
    {CTA_VARIANT && (
      <div
        class="relative z-10 hidden flex-col items-center text-center"
        data-variant="variant"
      >
        {CTA_VARIANT.showForm ? (
          <FormSubmission
            client:only="react"
            heading={CTA_VARIANT.heading}
            body={CTA_VARIANT.bodyText}
            layout="card"
            signupType={SignupType.Banner}
            source={source}
          />
        ) : (
          <>
            <SectionHeading
              headingType={HeadingType.h2}
              heading={CTA_VARIANT.heading}
              textAlignment={TextAlignment.center}
            />
            <div class="mt-4 flex flex-wrap justify-center gap-4 md:mt-12">
              <Button
                size="lg"
                href={variantHref}
                data-ph-capture-attribute-button-click={CTA_DEFAULTS.postHogButtonID}
                data-ph-capture-attribute-test-variant={CTA_VARIANT_IDS.variant}
              >
                {CTA_VARIANT.buttonText}
              </Button>
              <SectionHeading
                headingType={HeadingType.h3}
                heading={CTA_VARIANT.subHeading}
                textAlignment={TextAlignment.center}
              />
              <p>{CTA_VARIANT.bodyText}</p>
            </div>
          </>
        )}
      </div>
    )}
  </div>
</section>

<script>
  import { AB_TEST_ENABLED } from '@/constants/cta';

